contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 diff, uint256 limit, uint256 wagerAmount) public payable {
        require(limit > 0, "limit must be > 0");

        // Owner action: open public access.
        c.OpenToThePublic();

        // Set wager limit (also opens the gate for C.wager's require).
        c.AdjustBetAmounts(limit);

        // Set difficulty; must be > 0 to avoid division by zero later, and avoid difficulty / 2 == 1 trap? No trap needed here.
        c.AdjustDifficulty(diff);

        // Fund this contract with exactly the wager amount and wager.
        require(msg.value >= wagerAmount, "insufficient value");
        c.wager{value: wagerAmount}();

        // Read the pre-state: player's wager should now be recorded.
        bool hadWagerBefore = c.hasPlayerWagered(address(this));
        uint256 balanceBefore = c.ethBalance();

        // The play call is made immediately in the same block.
        // It must revert because timestamp is not strictly less than current block number.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // General rule: play called in the same block as the wager reverts and leaves the wager intact.
        // Also, because it reverted, no Ether can have left the contract.
        assert(playReverted && c.hasPlayerWagered(address(this)) && c.ethBalance() == balanceBefore);
    }

    receive() external payable {}
}

